import React, { useState } from 'react';
// useNavigate 훅을 import 해야 해!
import { useNavigate } from 'react-router-dom'; // 👈 이 부분을 추가!

const UserInfoTab = ({ userInfo }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState({
    ...userInfo,
    password: '',
    confirmPassword: '',
  }); 

  // useNavigate 훅을 사용해서 페이지 이동 함수를 가져와
  const navigate = useNavigate(); // 👈 이 부분을 추가!

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleCheckEmailDuplication = async () => {
    console.log(`이메일 중복 확인 요청: ${formData.email}`);
    
    if (formData.email === userInfo.email) {
      alert('현재 사용 중인 이메일입니다. 변경하시려면 다른 이메일을 입력해주세요. 😉');
      return;
    }

    try {
      // 실제 API 호출 부분 (예시)
      // const response = await fetch('/api/check-email-duplication', {
      //   method: 'POST',
      //   headers: { 'Content-Type': 'application/json' },
      //   body: JSON.stringify({ email: formData.email }),
      // });
      // const data = await response.json();

      // if (data.isDuplicated) { 
      //   alert('🚨 이미 사용 중인 이메일입니다! 다른 이메일을 사용해주세요. 😢');
      // } else {
      //   alert('✅ 사용 가능한 이메일입니다! 👍');
      // }

      // 가상 응답 (테스트용)
      const isDuplicated = formData.email === 'test@example.com';
      if (isDuplicated) {
        alert('🚨 이미 사용 중인 이메일입니다! 다른 이메일을 사용해주세요. 😢');
      } else {
        alert('✅ 사용 가능한 이메일입니다! 👍');
      }

    } catch (error) {
      console.error('이메일 중복 확인 중 오류 발생:', error);
      alert('이메일 중복 확인 중 오류가 발생하였습니다. 다시 시도해주세요. 😥');
    }
  };

  const handleCheckNicknameDuplication = async () => {
    console.log(`닉네임 중복 확인 요청: ${formData.nickname}`);

    if (formData.nickname === userInfo.nickname) {
      alert('현재 사용 중인 닉네임입니다. 변경하시려면 다른 닉네임을 입력해주세요. 😉');
      return;
    }

    try {
      // 실제 API 호출 부분 (예시)
      // const response = await fetch('/api/check-nickname-duplication', {
      //   method: 'POST',
      //   headers: { 'Content-Type': 'application/json' },
      //   body: JSON.stringify({ nickname: formData.nickname }),
      // });
      // const data = await response.json();

      // if (data.isDuplicated) { 
      //   alert('🚨 이미 사용 중인 닉네임입니다! 다른 닉네임을 사용해주세요. 😢');
      // } else {
      //   alert('✅ 사용 가능한 닉네임입니다! 👍');
      // }

      // 가상 응답 (테스트용)
      const isDuplicated = formData.nickname === '중복닉네임';
      if (isDuplicated) {
        alert('🚨 이미 사용 중인 닉네임입니다! 다른 닉네임을 사용해주세요. 😢');
      } else {
        alert('✅ 사용 가능한 닉네임입니다! 👍');
      }

    } catch (error) {
      console.error('닉네임 중복 확인 중 오류 발생:', error);
      alert('닉네임 중복 확인 중 오류가 발생하였습니다. 다시 시도해주세요. 😥');
    }
  };


  const handleSubmit = async (e) => { // 비동기 함수로 변경
    e.preventDefault();

    if (formData.password || formData.confirmPassword) { 
      if (formData.password !== formData.confirmPassword) {
        alert('비밀번호와 비밀번호 확인이 일치하지 않습니다! 다시 확인해주세요. 🧐');
        return;
      }
    }

    // ⭐ 여기에 실제 백엔드 회원 정보 수정 API 호출 로직을 넣어줘! ⭐
    // 예를 들어,
    try {
      // const response = await fetch('/api/user/update', { // 실제 API 엔드포인트
      //   method: 'PUT',
      //   headers: { 
      //     'Content-Type': 'application/json',
      //     'Authorization': `Bearer ${localStorage.getItem('token')}` // 토큰이 있다면 전송
      //   },
      //   body: JSON.stringify(formData),
      // });

      // if (!response.ok) {
      //   throw new Error('회원 정보 수정 실패');
      // }

      // const data = await response.json(); // 서버 응답 (필요하다면)
      
      alert('회원 정보가 성공적으로 수정되었습니다! 다시 로그인 해주세요. 🎉');
      console.log('수정된 정보:', formData);
      // setIsEditing(false); // 수정 완료 후 다시 로그인 페이지로 가므로 필요 없음

      // ✨ 로그인 페이지로 이동 ✨
      // 로그인 페이지 경로가 '/login'이라고 가정했어. 도몬의 실제 경로에 맞춰 수정해줘!
      navigate('/login'); 

    } catch (error) {
      console.error('회원 정보 수정 중 오류 발생:', error);
      alert('회원 정보 수정 중 오류가 발생하였습니다. 다시 시도해주세요. 😥');
    }
  };

  const handleWithdrawal = async () => { // 비동기 함수로 변경
    if (window.confirm('🚨 정말로 회원 탈퇴하시겠습니까? 모든 정보가 영구적으로 삭제됩니다! 😱')) {
      // ⭐ 여기에 실제 백엔드 회원 탈퇴 API 호출 로직을 넣어줘! ⭐
      try {
        // const response = await fetch('/api/user/withdraw', { // 실제 API 엔드포인트
        //   method: 'DELETE',
        //   headers: { 
        //     'Content-Type': 'application/json',
        //     'Authorization': `Bearer ${localStorage.getItem('token')}` // 토큰이 있다면 전송
        //   },
        // });

        // if (!response.ok) {
        //   throw new Error('회원 탈퇴 실패');
        // }

        alert('회원 탈퇴가 완료되었습니다. 그동안 이용해주셔서 감사합니다! 👋');
        // ✨ 탈퇴 후 로그인 페이지로 이동 ✨
        navigate('/login'); 

      } catch (error) {
        console.error('회원 탈퇴 중 오류 발생:', error);
        alert('회원 탈퇴 중 오류가 발생하였습니다. 다시 시도해주세요. 😥');
      }
    }
  };

  return (
    <div className="tab-content-section user-info-tab">
      <h3 className="tab-content-title">회원 정보 {!isEditing ? '보기' : '수정'}</h3>

      {!isEditing ? (
        <>
          <div className="info-item">
            <span className="info-label">아이디</span>
            <span className="info-value" style={{ textAlign: 'left', flexGrow: 1 }}>{userInfo.userId || '정보 없음'}</span> 
          </div>
          <div className="info-item">
            <span className="info-label">이메일</span>
            <span className="info-value" style={{ textAlign: 'left', flexGrow: 1 }}>{userInfo.email || '정보 없음'}</span>
          </div>
          <div className="info-item">
            <span className="info-label">닉네임</span>
            <span className="info-value" style={{ textAlign: 'left', flexGrow: 1 }}>{userInfo.nickname || '정보 없음'}</span> 
          </div>
          <div className="info-item">
            <span className="info-label">가입일</span>
            <span className="info-value" style={{ textAlign: 'left', flexGrow: 1 }}>{userInfo.registeredDate || '정보 없음'}</span>
          </div>
          <button className="action-button" onClick={() => setIsEditing(true)}>정보 수정 ✏️</button>
        </>
      ) : (
        <form onSubmit={handleSubmit}>
          {/* 이메일 수정 필드 */}
          <div className="info-item action-input-group">
            <label className="info-label" htmlFor="email">이메일</label>
            <div className="input-with-button">
              <input
                type="email"
                id="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                className="info-value-input"
                required 
              />
              <button type="button" className="check-button" onClick={handleCheckEmailDuplication}>중복 확인</button>
            </div>
          </div>
          
          {/* 닉네임 수정 필드 */}
          <div className="info-item action-input-group">
            <label className="info-label" htmlFor="nickname">닉네임</label>
            <div className="input-with-button">
              <input
                type="text"
                id="nickname"
                name="nickname"
                value={formData.nickname}
                onChange={handleChange}
                className="info-value-input"
                required 
              />
              <button type="button" className="check-button" onClick={handleCheckNicknameDuplication}>중복 확인</button>
            </div>
          </div>

          {/* 비밀번호 변경 필드 */}
          <div className="info-item action-input-group">
            <label className="info-label" htmlFor="password">새 비밀번호</label>
            <div className="input-with-button">
              <input
                type="password"
                id="password"
                name="password"
                value={formData.password}
                onChange={handleChange}
                className="info-value-input"
                placeholder="변경하실 비밀번호를 입력해주세요."
                autoComplete="new-password" 
              />
            </div>
          </div>
          <div className="info-item action-input-group">
            <label className="info-label" htmlFor="confirmPassword">새 비밀번호 확인</label>
            <div className="input-with-button">
              <input
                type="password"
                id="confirmPassword"
                name="confirmPassword"
                value={formData.confirmPassword}
                onChange={handleChange}
                className="info-value-input"
                placeholder="비밀번호를 다시 한번 입력해주세요."
                autoComplete="new-password" 
              />
            </div>
          </div>
          
          <div className="button-group" style={{ display: 'flex', justifyContent: 'flex-end', gap: '10px', marginTop: '30px' }}>
            <button type="submit" className="action-button">저장 ✅</button>
            <button type="button" className="action-button" onClick={() => setIsEditing(false)}>취소 ↩️</button>
            <button type="button" className="action-button delete-button" onClick={handleWithdrawal}>회원 탈퇴 🗑️</button>
          </div>
        </form>
      )}
    </div>
  );
};

export default UserInfoTab;
